test('The x-y scan has its own page, directional eyes and replayable persistent ray highlights',()=>{
 const h=boot(undefined,'file:///C:/tetris-studio/index.html?lesson=xy-scan'),body=h.elements.courseIntroBody,X=h.context.TetrisXYScan;assert.equal(h.elements.courseIntroTitle.textContent,'The x-y scan');const intro=body.children.find(e=>e.className==='xy-eye-introduction');assert.equal(intro.children.length,2);assert(intro.children[0].children[0].children[0].style.transform.includes('rotate(90deg)'));assert(!intro.children[1].children[0].children[0].style.transform.includes('rotate'));
 const demos=body.children.find(e=>e.className==='xy-scan-demos'),chooser=body.children.find(e=>e.className==='xy-example-choices'),vertical=demos.children[0],horizontal=demos.children[1],v=vertical.children[1].children[0],heye=horizontal.children[1].children[1];assert.equal(vertical.children[0].children[0].textContent,'▶');assert.equal(vertical.children[0].children[0].attributes['aria-label'],'Replay vertical scan');assert.equal(v.width,144);assert.equal(v.height,184);assert(!v.ops.some(o=>o.alpha<1),'unplayed board has no highlights');assert(!horizontal.children[1].children[0].ops.some(o=>o.alpha<1));const initialHoleMarks=v.ops.filter(o=>o.color==='#ff526b'&&o.alpha===.65).length,firstEye=vertical.children[1].children[1].style.left,firstHorizontal=heye.style.top;
 h.animate(100);for(let t=200;t<=900;t+=100)h.animate(t);assert.notEqual(vertical.children[1].children[1].style.left,firstEye);assert.notEqual(heye.style.top,firstHorizontal);for(let t=1000;t<=7200;t+=100)h.animate(t);assert(vertical.children[2].textContent.includes('All columns scanned'));assert(v.ops.some(o=>o.color==='#ff526b'&&o.alpha===.65));assert(horizontal.children[2].textContent.includes('Scan complete'));
 vertical.children[0].children[0].onclick();assert.equal(vertical.children[1].children[1].style.left,firstEye);assert.equal(v.ops.filter(o=>o.color==='#ff526b'&&o.alpha===.65).length,initialHoleMarks,'replay restores the first scanned column');chooser.children[2].onclick();assert.equal(chooser.children[2].attributes['aria-pressed'],'true');assert(body.children.find(e=>e.className==='xy-example-note').textContent.includes('column 5'));
 const url=h.context.location.href;for(const id of ['initialLevelPicker','freeStartPicker','stackEditor','mistakeGallery','puzzleLibrary'])h.elements[id].hidden=true;h.key('ArrowRight');assert.equal(h.context.location.href,url,'scan page cannot navigate hidden playback');h.context.TetrisCourse.openLesson('roof-burns');assert(!h.elements.courseIntroBody.children.some(e=>e.className==='xy-scan-demos'));
 const reduced=boot(undefined,'file:///C:/tetris-studio/index.html?lesson=xy-scan',{matchMedia:()=>({matches:true})});const grid=reduced.elements.courseIntroBody.children.find(e=>e.className==='xy-scan-demos');assert(grid.children[0].children[2].textContent.includes('Board ready'));const reducedEye=grid.children[0].children[1].children[1],endPosition=reducedEye.style.left;grid.children[0].children[0].children[0].onclick();assert.equal(reducedEye.style.visibility,'hidden','replay begins on a clean board');reduced.animate(100);for(let t=200;t<=900;t+=100)reduced.animate(t);assert.notEqual(reducedEye.style.left,endPosition,'explicit replay animates even with reduced motion');
});


test('Eye scans wait until visible, pause out of view and disconnect on leaving',()=>{
 const observers=[];class Observer{constructor(callback){this.callback=callback;this.targets=[];this.disconnected=false;observers.push(this);}observe(target){this.targets.push(target);}disconnect(){this.disconnected=true;}}
 const h=boot(undefined,'file:///C:/tetris-studio/index.html?lesson=xy-scan',{IntersectionObserver:Observer}),observer=observers.at(-1),demos=h.elements.courseIntroBody.children.find(e=>e.className==='xy-scan-demos'),first=demos.children[0],eye=first.children[1].children[1],canvas=first.children[1].children[0],start=eye.style.left;assert.equal(observer.targets.length,2);h.animate(100);h.animate(5100);assert.equal(eye.style.left,start,'reading the intro does not consume the scan');assert(first.children[2].textContent.includes('into view'));
 observer.callback([{target:canvas,isIntersecting:true}]);h.animate(5200);for(let t=5300;t<=6000;t+=100)h.animate(t);assert.notEqual(eye.style.left,start,'visible eye scans the columns');const paused=eye.style.left;observer.callback([{target:canvas,isIntersecting:false}]);h.animate(6100);h.animate(9100);assert.equal(eye.style.left,paused,'offscreen animation pauses');observer.callback([{target:canvas,isIntersecting:true}]);h.animate(9200);for(let t=9300;t<=9900;t+=100)h.animate(t);assert.notEqual(eye.style.left,paused,'returning resumes the scan');h.context.TetrisCourse.openLesson('roof-burns');assert(observer.disconnected);observer.callback([{target:canvas,isIntersecting:true}]);assert.equal(h.elements.courseIntroTitle.textContent,'Roof burns (rooftop burns)');
});


