test('Horizontal scan automatically shows every fitting piece and its rated clear result',()=>{
 const h=boot(undefined,'file:///C:/tetris-studio/index.html?lesson=xy-scan'),X=h.context.TetrisXYScan,body=h.elements.courseIntroBody,card=body.children.find(e=>e.className==='xy-scan-demos').children[1],stage=card.children[1],verdict=stage.children[2],options=card.children.find(e=>e.className==='xy-burn-options'),source=h.context.TetrisCore.demos().find(s=>s.roofBurn?.key===X.EXAMPLES[0].key),count=X.opportunities(source).solutions.length,start=X.model(source,'horizontal',0).scanDuration;
 h.animate(100);for(let t=200;t<start;t+=100)h.animate(t);assert.equal(options.children[1].style.visibility,'hidden');assert(verdict.hidden);let time=start+100;for(let i=0;i<count;i++){const until=start+(i+1)*X.REVIEW_MS+100;let showed=false;for(;time<until;time+=100){h.animate(time);if(!verdict.hidden)showed=true;}assert(showed,'a result is animated for placement '+i);}for(let n=0;n<3;n++){h.animate(time);time+=100;}assert(card.children[2].textContent.includes('All placements shown'));const choices=options.children[1].children[2].children;assert(choices.some(b=>b.children.at(-1).textContent==='Meh'));assert(choices.some(b=>b.children.at(-1).textContent.startsWith('Good')));const meh=choices.find(b=>b.children.at(-1).textContent==='Meh');meh.onclick();assert(verdict.hidden,'selecting a placement restarts its animation');for(let n=0;n<40;n++){h.animate(time);time+=100;}assert.equal(verdict.textContent,'Meh');assert.equal(verdict.hidden,false);assert(verdict.className.includes('meh'));
});


